<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {purchaseApi} from '@/api/purchases'
import type {PurchaseRecord} from '@/api/purchases'
const rows=ref<PurchaseRecord[]>([]),search=ref(''),status=ref(''),loading=ref(false),error=ref(''),page=ref(1),lastPage=ref(1)
const money=(v:number)=>new Intl.NumberFormat('en-BD',{style:'currency',currency:'BDT'}).format((v||0)/100)
async function load(){loading.value=true;try{const r=await purchaseApi.purchases({search:search.value||undefined,status:status.value||undefined,page:page.value});rows.value=r.data.data;lastPage.value=r.data.meta?.last_page||1}catch(e:any){error.value=e?.response?.data?.message||'Could not load purchases.'}finally{loading.value=false}}
watch([search,status],()=>{page.value=1;load()});onMounted(load)
</script>
<template><section class="page"><header><div><small>PROCUREMENT</small><h1>Purchases</h1><p>Create purchase orders and receive stock into warehouses.</p></div><RouterLink :to="{name:'purchases.create'}">＋ New purchase</RouterLink></header><p v-if="error" class="error">{{error}}</p><div class="card"><div class="filters"><input v-model="search" placeholder="Search purchase or supplier"><select v-model="status"><option value="">All statuses</option><option value="draft">Draft</option><option value="received">Received</option><option value="cancelled">Cancelled</option></select></div><div class="scroll"><table><thead><tr><th>Purchase no.</th><th>Supplier</th><th>Warehouse</th><th>Date</th><th>Items</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in rows" :key="p.id"><td><b>{{p.purchase_no}}</b></td><td>{{p.supplier?.name||'—'}}</td><td>{{p.warehouse?.name||'—'}}</td><td>{{p.ordered_at?new Date(p.ordered_at).toLocaleDateString():'—'}}</td><td>{{p.items_count??'—'}}</td><td><b>{{money(p.grand_total)}}</b></td><td><span :class="p.status">{{p.status}}</span></td><td><RouterLink :to="{name:'purchases.show',params:{id:p.id}}">View</RouterLink></td></tr><tr v-if="!rows.length"><td colspan="8" class="empty">{{loading?'Loading...':'No purchases found.'}}</td></tr></tbody></table></div><footer><button :disabled="page<=1" @click="page--;load()">Previous</button>Page {{page}} of {{lastPage}}<button :disabled="page>=lastPage" @click="page++;load()">Next</button></footer></div></section></template>
<style scoped>
.page{color:#172033}.page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page small{font-size:10px;letter-spacing:1.2px;color:#64748b;font-weight:800}.page h1{font-size:25px;margin:5px 0}.page p{font-size:13px;color:#7b8798}.page header a{background:#172033;color:white;text-decoration:none;border-radius:8px;padding:11px 14px;font-size:12px}.card{background:white;border:1px solid #e7ebf1;border-radius:13px;overflow:hidden}.filters{display:flex;gap:10px;padding:15px}.filters input,.filters select{padding:10px;border:1px solid #dfe5ed;border-radius:8px}.filters input{width:300px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:13px 14px;border-top:1px solid #edf0f4;font-size:12px}th{background:#f8fafc;color:#64748b;text-transform:uppercase;font-size:10px}td{color:#475569}td a{color:#2563eb}.draft,.received,.cancelled{padding:5px 8px;border-radius:20px;background:#fef3c7;color:#92400e}.received{background:#ecfdf5;color:#047857}.cancelled{background:#f1f5f9;color:#64748b}.empty{text-align:center;padding:30px}footer{display:flex;justify-content:flex-end;align-items:center;gap:12px;padding:14px;font-size:11px;color:#64748b}footer button{background:white;border:1px solid #dfe5ed;border-radius:7px;padding:7px 10px}.error{color:#be123c}
</style>
